	/**  Optional profile name. */
	name: string | null,
	/**  Remote username; it must not be empty. */
	username: string,
	/**  Credential identifier, or `null` to resolve any usable credential. */
	credential: string | null,
	/**  Route identifier, or `null` for direct access. */
