	/**  Local terminal profile name. */
	terminalProfile: string | null,
	/**  Startup command. */
	startupCommand: string | null,
	/**  Agent forwarding toggle. */
	agentForwarding: boolean,
	/**  Complete replacement for saved tunnels started with this login. */
